```typescript
async function processOrder(order: Order): Promise<OrderResult> {
  const inventory = await retry(() => inventoryService.reserve(order.items), { retries: 3, delay: 1000 });
  const payment = await retry(() => paymentProvider.charge(order.total, order.paymentMethod), { retries: 3, delay: 1000 });
  const notification = await retry(() => notificationService.sendConfirmation(order, payment), { retries: 3, delay: 1000 });
  return { orderId: order.id, inventory, payment, notification };
}

async function retry<T>(fn: () => Promise<T>, opts: { retries: number; delay: number }): Promise<T> {
  for (let i = 0; i <= opts.retries; i++) {
    try {
      return await fn();
    } catch (err) {
      if (i === opts.retries) throw err;
      await new Promise(r => setTimeout(r, opts.delay));
    }
  }
  throw new Error('unreachable');
}
```

